<?php
require_once __DIR__ . '/../app/application.php';requireAuthentication('../account/login.php');$customer=dbFetchOne('SELECT id FROM customers WHERE user_id=:user',['user'=>currentUserId()]);$contract=dbFetchOne('SELECT rc.*,cv.snapshot_json,cv.terms_text,cv.version_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN contract_versions cv ON cv.contract_id=rc.id AND cv.version_number=rc.current_version WHERE rc.id=:id AND r.customer_id=:customer ORDER BY cv.id LIMIT 1',['id'=>(int)($_GET['id']??0),'customer'=>$customer['id']??0]);if(!$contract){http_response_code(404);exit('Contract not found.');}$data=json_decode($contract['snapshot_json'],true);?><!doctype html><html><head><meta charset="utf-8"><title><?=e($contract['contract_number'])?></title><link rel="stylesheet" href="../backoffice/assets/app.css"></head><body><main class="page"><button class="btn secondary" onclick="window.print()">Print / Save PDF</button><h1>Rental contract <?=e($contract['contract_number'])?></h1><div class="grid"><section class="card"><h2>Customer</h2><p><?=e($data['customer']['name']??'')?></p><p><?=e($data['customer']['identity_number']??'')?></p></section><section class="card"><h2>Vehicle</h2><p><?=e($data['vehicle']['description']??'')?></p><p><?=e($data['vehicle']['registration_number']??'')?></p></section></div><section class="card"><p><?=e($data['period']['pickup_at']??'')?> — <?=e($data['period']['return_at']??'')?></p><p><?=money($data['pricing']['total']??0,$data['currency']??'MAD')?></p><p><?=nl2br(e($contract['terms_text']))?></p></section></main></body></html>
